CREATE OR REPLACE FUNCTION public.guard_retired_company_plate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.company_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.companies WHERE id=NEW.company_id AND deleted_at IS NOT NULL) AND (NEW.status<>'cancelled' OR NEW.blocked_by_admin IS DISTINCT FROM true) THEN RAISE EXCEPTION 'Cliente excluído: esta plaquinha está invalidada.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_retired_company_plate BEFORE INSERT OR UPDATE ON public.plates FOR EACH ROW EXECUTE FUNCTION public.guard_retired_company_plate();
CREATE OR REPLACE FUNCTION public.is_company_subscription_active(_company_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.companies c ON c.id=s.company_id WHERE s.company_id=_company_id AND c.deleted_at IS NULL AND s.expires_at>now() AND s.status='active'); $$;
CREATE OR REPLACE FUNCTION public.public_company_by_code(_code text) RETURNS TABLE(name text,website_url text,logo_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.name,c.website_url,c.logo_url FROM public.companies c JOIN public.plates p ON p.company_id=c.id WHERE p.qr_code=_code AND c.deleted_at IS NULL AND p.status='linked' AND NOT p.blocked_by_client AND NOT p.blocked_by_admin LIMIT 1; $$;
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('public.company_addons(uuid)'::regprocedure) INTO definition;
 definition:=replace(definition,'BEGIN','BEGIN IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=_company_id AND deleted_at IS NULL) THEN RETURN jsonb_build_object(''waiter'',jsonb_build_object(''active'',false),''menu'',jsonb_build_object(''active'',false)); END IF;'); EXECUTE definition;
 SELECT pg_get_functiondef('public.request_addon(uuid,text,text)'::regprocedure) INTO definition;
 definition:=replace(definition,'SELECT * INTO st FROM public.settings WHERE id=true;','PERFORM 1 FROM public.companies WHERE id=_company_id AND deleted_at IS NULL FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION ''Cliente excluído ou não encontrado.''; END IF; SELECT * INTO st FROM public.settings WHERE id=true;'); EXECUTE definition;
 SELECT pg_get_functiondef('public.confirm_admin_payment(uuid,uuid)'::regprocedure) INTO definition;
 definition:=replace(definition,'IF p.kind::text=''addon'' THEN','IF p.kind<>''plate'' THEN PERFORM 1 FROM public.companies WHERE id=p.company_id AND deleted_at IS NULL FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION ''Cliente excluído: não é possível renovar seus serviços.''; END IF; END IF; IF p.kind::text=''addon'' THEN'); EXECUTE definition;
END $$;